let keyframesState: any[] = [];

interface DesignerUser {
  id: string;
  name: string;
  color: string;
  selectedObjectId: string | null;
  ws: WebSocket;
}

const connectedUsers = new Map<string, DesignerUser>();

const DESIGNER_NAMES = [
  "Sculptor Neo", "Vertices Pro", "Render Guru", "Vector Chef", 
  "Polygon Ace", "Shading Master", "Keyframe Sage", "Grid Carver"
];

const DESIGNER_COLORS = [
  "#f97316", // Orange
  "#3b82f6", // Blue
  "#10b981", // Green
  "#a855f7", // Purple
  "#ec4899", // Pink
  "#eab308", // Yellow
  "#06b6d4"  // Cyan
];

// Helper to broadcast presence updates to all clients
function broadcastPresence() {
  const usersList = Array.from(connectedUsers.values()).map(u => ({
    id: u.id,
    name: u.name,
    color: u.color,
    selectedObjectId: u.selectedObjectId
  }));

  const payload = JSON.stringify({
    type: "presence:sync",
    users: usersList
  });

  for (const user of connectedUsers.values()) {
    if (user.ws.readyState === WebSocket.OPEN) {
      user.ws.send(payload);
    }
  }
}

// Helper to broadcast message to all clients *except* sender
function broadcastToOthers(senderId: string, payloadStr: string) {
  for (const [id, user] of connectedUsers.entries()) {
    if (id !== senderId && user.ws.readyState === WebSocket.OPEN) {
      user.ws.send(payloadStr);
    }
  }
}

// Helper to broadcast to *all* clients
function broadcastToAll(payloadStr: string) {
  for (const user of connectedUsers.values()) {
    if (user.ws.readyState === WebSocket.OPEN) {
      user.ws.send(payloadStr);
    }
  }
}

// Express endpoints for retrieving/updating state standardly (or client can use Websockets)
app.get("/api/scene", (req, res) => {
  res.json({ sceneObjects: sceneObjectsState, keyframes: keyframesState });
});

// Configure Vite middleware or Static files build path
async function startServer() {
  if (process.env.NODE_ENV !== "production") {
    const vite = await createViteServer({
      server: { middlewareMode: true },
      appType: "spa",
    });
    app.use(vite.middlewares);
  } else {
    const distPath = path.join(process.cwd(), "dist");
    app.use(express.static(distPath));
    app.get("*", (req, res) => {
      res.sendFile(path.join(distPath, "index.html"));
    });
  }

  // Wrap express app into an HTTP Server to support WebSockets upgrades
  const server = http.createServer(app);

  // Initialize WebSocket server on the same HTTP server port 3000
  const wss = new WebSocketServer({ server });

  wss.on("connection", (ws: WebSocket) => {
    // Assign a designer profile
    const userId = "user_" + Math.random().toString(36).substring(2, 9);
    const chosenName = DESIGNER_NAMES[Math.floor(Math.random() * DESIGNER_NAMES.length)] + " #" + Math.floor(Math.random() * 100);
    const chosenColor = DESIGNER_COLORS[Math.floor(Math.random() * DESIGNER_COLORS.length)];

    const newUser: DesignerUser = {
      id: userId,
      name: chosenName,
      color: chosenColor,
      selectedObjectId: null,
      ws
    };

    connectedUsers.set(userId, newUser);

    console.log(`[WS Connection] Joined ${chosenName} (ID: ${userId})`);

    // 1. Welcome the client & assign profile
    ws.send(JSON.stringify({
      type: "welcome",
      profile: {
        id: userId,
        name: chosenName,
        color: chosenColor
      }
    }));

    // 2. Transmit the standard starting 3D state
    ws.send(JSON.stringify({
      type: "init",
      sceneObjects: sceneObjectsState,
      keyframes: keyframesState
    }));

    // 3. Broadcast to all other clients that a user joined
    broadcastToOthers(userId, JSON.stringify({
      type: "chat:message",
      id: "joined_" + userId,
      sender: "system",
      text: `${chosenName} joined the collaborative workspace.`,
      timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
    }));

    // 4. Update the active connected users panel
    broadcastPresence();

    // Client event processor
    ws.on("message", (rawMessage: string) => {
      try {
        const message = JSON.parse(rawMessage);

        switch (message.type) {
          case "scene:update": {
            // Read-Modify-Write state update on server
            if (Array.isArray(message.sceneObjects)) {
              sceneObjectsState = message.sceneObjects;
            }
            if (Array.isArray(message.keyframes)) {
              keyframesState = message.keyframes;
            }

            // Sync with other active clients (prevents infinite sync/stuttering)
            broadcastToOthers(userId, JSON.stringify({
              type: "scene:sync",
              sceneObjects: sceneObjectsState,
              keyframes: keyframesState,
              senderId: userId
            }));
            break;
          }

          case "presence:update": {
            if (newUser) {
              newUser.selectedObjectId = message.selectedObjectId ?? null;
              broadcastPresence();
            }
            break;
          }

          case "chat:sendMessage": {
            if (message.text) {
              const chatMsg = JSON.stringify({
                type: "chat:message",
                id: Math.random().toString(36).substring(2, 9),
                sender: "user",
                senderName: chosenName,
                senderColor: chosenColor,
                text: message.text,
                timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
              });
              broadcastToAll(chatMsg);
            }
            break;
          }

          default:
            break;
        }

      } catch (err) {
        console.error("Error parsing WebSocket packet:", err);
      }
    });

    ws.on("close", () => {
      connectedUsers.delete(userId);
      console.log(`[WS Connection] Left ${chosenName} (ID: ${userId})`);

      // Broadcast client leave event
      broadcastToOthers(userId, JSON.stringify({
        type: "chat:message",
        id: "left_" + userId,
        sender: "system",
        text: `${chosenName} left the workspace.`,
        timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
      }));

      // Broadcast updated presence sync
      broadcastPresence();
    });
  });

  server.listen(PORT, "0.0.0.0", () => {
    console.log(`Blender Web server active at http://localhost:${PORT}`);
  });
}

startServer();
